// The part number is the identifier stamped into CAD, Blender, supplier files
// and order snapshots (docs/BUILD-ROADMAP-IDENTITY.md, gaps G-1..G-3). It is
// generated by the server, never typed, and never changed. These read the
// source so a client-supplied number or a writable part number fails the
// build instead of surfacing as two parts with one number a year later.
import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

const read = (p) => readFileSync(new URL("../" + p, import.meta.url), "utf8");
const api = read("supabase/functions/portal-api/index.ts");
const app = read("assets/app.js");

const block = (src, startMarker, endMarker) => {
  const start = src.indexOf(startMarker);
  const end = src.indexOf(endMarker, start + 1);
  assert.ok(start >= 0 && end > start, `block ${startMarker} not found`);
  return src.slice(start, end);
};

test("part numbers are generated in exactly one place, on the server", () => {
  assert.equal((api.match(/`RR-\$\{/g) || []).length, 1, "portal-api builds RR- numbers in more than one place");
  assert.equal((app.match(/`RR-\$\{/g) || []).length, 0, "the browser must not invent part numbers");
  assert.equal((app.match(/function genPN/g) || []).length, 0, "a client-side generator came back");
});

test("no create path reads a part number from the request", () => {
  const create = block(api, 'action === "addComponent"', "\n  if (action === ");
  assert.ok(!/part_number\s*\}?\s*=\s*body|body\.part_number/.test(create), "addComponent takes part_number from the client");
  assert.ok(/newPartNumber\(\)/.test(create), "addComponent does not generate the number");
  assert.ok(!/part_number: requestedPN/.test(api), "variant creation takes part_number from the client");
});

test("the browser never sends a part number", () => {
  assert.ok(!/part_number:\s*(pn|newPN|pnInp)\.value/.test(app), "a form still sends part_number");
});

test("updateComponent never writes part_number", () => {
  const upd = block(api, 'action === "updateComponent"', 'action === "setComponentStatus"');
  assert.ok(!/patch\.part_number\s*=/.test(upd), "updateComponent assigns patch.part_number");
  assert.ok(/cannot be changed/.test(upd), "updateComponent no longer refuses a changed part number");
});
